# Generated by VOCUY for DaVinci Resolve 18 or later.
# Open a project, then either:
#   - Workspace > Console > Py3, and enter: exec(open(r'/path/to/this_file.py', encoding='utf-8').read())
#   - or copy this file into Resolve's Scripts/Edit folder and choose Workspace > Scripts.
# Keep the referenced WAV and SRT files. This script adds a bin and timelines to the current project.
import json
import os
import sys

DATA = json.loads(__VOCUY_MANIFEST__)
SETTINGS = DATA['settings']
MARKER_COLORS = ('Green', 'Blue', 'Red')
CLIP_COLORS = ('Green', 'Blue', 'Orange')
FPS_NAMES = {23.976: '23.976', 24: '24', 25: '25', 29.97: '29.97', 30: '30',
             50: '50', 59.94: '59.94', 60: '60'}


class VocuyError(Exception):
    pass


def report(message):
    print('VOCUY: ' + message)


def get_resolve():
    scope = globals()
    if scope.get('resolve'):
        return scope['resolve']
    if scope.get('app'):
        try:
            found = scope['app'].GetResolve()
            if found:
                return found
        except Exception:
            pass
    try:
        import DaVinciResolveScript as bmd
    except ImportError:
        modules = {
            'darwin': '/Library/Application Support/Blackmagic Design/DaVinci Resolve/Developer/Scripting/Modules',
            'win32': os.path.join(os.environ.get('PROGRAMDATA', r'C:\ProgramData'),
                                  'Blackmagic Design', 'DaVinci Resolve', 'Support', 'Developer', 'Scripting', 'Modules'),
        }.get(sys.platform, '/opt/resolve/Developer/Scripting/Modules')
        sys.path.append(modules)
        try:
            import DaVinciResolveScript as bmd
        except ImportError:
            return None
    return bmd.scriptapp('Resolve')


def script_folder():
    location = globals().get('__file__')
    return os.path.dirname(os.path.abspath(location)) if location else None


def locate(entry):
    """Prefer a path relative to this script so a moved folder keeps working."""
    folder = script_folder()
    if folder and entry.get('relative_path'):
        candidate = os.path.join(folder, *entry['relative_path'].split('/'))
        if os.path.isfile(candidate):
            return candidate
    return entry['path'] if os.path.isfile(entry['path']) else None


def same_file(a, b):
    return os.path.normcase(os.path.normpath(a or '')) == os.path.normcase(os.path.normpath(b or ''))


def fps_value(text):
    try:
        return float(str(text).split()[0])
    except (ValueError, IndexError):
        return None


def unique_timeline_name(project, name):
    existing = set()
    for index in range(1, (project.GetTimelineCount() or 0) + 1):
        timeline = project.GetTimelineByIndex(index)
        if timeline:
            existing.add(timeline.GetName())
    candidate, number = name, 2
    while candidate in existing:
        candidate = '%s (%d)' % (name, number)
        number += 1
    return candidate


def main():
    resolve = get_resolve()
    if not resolve:
        raise VocuyError('Could not connect to DaVinci Resolve. Run this script from Workspace > Console or Workspace > Scripts.')
    project = resolve.GetProjectManager().GetCurrentProject()
    if not project:
        raise VocuyError('Open or create a project, then run this script again.')

    # Validate every reference before changing the project.
    paths = []
    for asset in DATA['assets']:
        path = locate(asset)
        if not path:
            raise VocuyError('audio file missing: %s\nRestore the WAV files and run this script again.' % asset['name'])
        paths.append(path)
    subtitle_paths = []
    for timeline in DATA['timelines']:
        entry = timeline.get('subtitles')
        path = locate(entry) if entry else None
        if entry and not path:
            raise VocuyError('subtitle file missing: %s\nRestore the SRT files and run this script again.' % entry['path'])
        subtitle_paths.append(path)

    fps_name = FPS_NAMES[SETTINGS['fps']]
    # The frame rate can only change before a project has timelines.
    if not project.GetTimelineCount():
        project.SetSetting('timelineFrameRate', fps_name)
        project.SetSetting('timelineResolutionWidth', str(SETTINGS['width']))
        project.SetSetting('timelineResolutionHeight', str(SETTINGS['height']))
    current_fps = fps_value(project.GetSetting('timelineFrameRate'))
    if current_fps is None or abs(current_fps - SETTINGS['fps']) > 0.001:
        raise VocuyError('This project uses %s fps but the export uses %s fps. Run the script in a new project, '
                         'or export again at %s fps.' % (project.GetSetting('timelineFrameRate'), fps_name,
                                                          project.GetSetting('timelineFrameRate')))

    pool = project.GetMediaPool()
    created_folders, created_timelines, created_clips = [], [], []
    try:
        root = pool.AddSubFolder(pool.GetRootFolder(), 'VOCUY - ' + DATA['name'])
        if not root:
            raise VocuyError('Could not create a Media Pool bin.')
        created_folders.append(root)
        audio_bin = pool.AddSubFolder(root, 'Audio')
        timeline_bin = pool.AddSubFolder(root, 'Timelines')
        subtitle_bin = pool.AddSubFolder(root, 'Subtitles') if any(subtitle_paths) else None

        pool.SetCurrentFolder(audio_bin)
        imported = pool.ImportMedia(paths) or []
        created_clips.extend(imported)
        items = []
        for index, path in enumerate(paths):
            match = [i for i in imported if same_file(i.GetClipProperty('File Path'), path)]
            if not match and len(imported) == len(paths):
                match = [imported[index]]
            if not match:
                raise VocuyError('Resolve could not import %s.' % os.path.basename(path))
            items.append(match[0])

        manual_subtitles = []
        for number, timeline_data in enumerate(DATA['timelines']):
            pool.SetCurrentFolder(timeline_bin)
            name = unique_timeline_name(project, timeline_data['name'])
            timeline = pool.CreateEmptyTimeline(name)
            if not timeline:
                raise VocuyError('Could not create timeline %s.' % name)
            created_timelines.append(timeline)
            project.SetCurrentTimeline(timeline)
            timeline.SetSetting('useCustomSettings', '1')
            timeline.SetSetting('timelineResolutionWidth', str(SETTINGS['width']))
            timeline.SetSetting('timelineResolutionHeight', str(SETTINGS['height']))
            while (timeline.GetTrackCount('audio') or 0) < timeline_data['tracks']:
                if not (timeline.AddTrack('audio', 'mono') or timeline.AddTrack('audio')):
                    raise VocuyError('Could not add audio tracks to %s.' % name)
            start = timeline.GetStartFrame()
            for clip in timeline_data['clips']:
                color = max(0, min(2, clip['speaker'] - 1))
                placed = pool.AppendToTimeline([{
                    'mediaPoolItem': items[clip['asset']], 'startFrame': 0, 'endFrame': clip['length'] - 1,
                    'mediaType': 2, 'trackIndex': clip['track'], 'recordFrame': start + clip['start']}])
                if not placed:
                    raise VocuyError('Could not place %s on %s.' % (clip['name'], name))
                item = placed[0]
                try:
                    item.SetName(clip['name'])
                except Exception:
                    pass
                item.SetClipColor(CLIP_COLORS[color])
                for frame, duration, text in clip['markers']:
                    item.AddMarker(frame, MARKER_COLORS[color], text, text, max(1, duration), '')
            path = subtitle_paths[number]
            if path:
                pool.SetCurrentFolder(subtitle_bin)
                subtitle = (pool.ImportMedia([path]) or [None])[0]
                before = timeline.GetTrackCount('subtitle') or 0
                if subtitle:
                    created_clips.append(subtitle)
                    try:
                        pool.AppendToTimeline([subtitle])
                    except Exception:
                        pass
                # Keep imported captions only when Resolve placed them at their timecodes.
                expected = start + timeline_data['subtitles']['first_frame']
                placed = []
                if (timeline.GetTrackCount('subtitle') or 0) > before:
                    placed = timeline.GetItemListInTrack('subtitle', before + 1) or []
                if not placed or abs(placed[0].GetStart() - expected) > 1:
                    if placed:
                        timeline.DeleteClips(placed)
                    manual_subtitles.append(name)
        if created_timelines:
            project.SetCurrentTimeline(created_timelines[0])
    except Exception:
        # Remove only objects made by this invocation, preserving the user's project.
        for cleanup in (lambda: pool.DeleteTimelines(created_timelines),
                        lambda: pool.DeleteClips(created_clips),
                        lambda: pool.DeleteFolders(created_folders)):
            try:
                cleanup()
            except Exception:
                pass
        raise

    report('created %d timeline(s), using %d recording(s).' % (len(created_timelines), len(paths)))
    if manual_subtitles:
        report('drag each SRT from the Subtitles bin to the start of its timeline: ' + ', '.join(manual_subtitles))
    report('Save your project to keep the timelines.')


try:
    main()
except VocuyError as error:
    report(str(error))
except Exception as error:
    report('could not create the timelines.\n%s' % error)
